# Fetch closed PRs with title, body, and changed files via GraphQL pagination.
node --input-type=module << 'EOF'
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const query = `
query($cursor: String) {
  repository(owner: "vitalitychems-dot", name: "TESSERA") {
    pullRequests(states: CLOSED, first: 50, after: $cursor, orderBy: {field: CREATED_AT, direction: ASC}) {
      pageInfo { hasNextPage endCursor }
      nodes {
        number
        title
        body
        merged
        files(first: 100) { nodes { path } }
      }
    }
  }
}`;

const all = [];
let cursor = null;
for (let page = 0; page < 20; page++) {
  const args = ["api", "graphql", "-f", `query=${query}`];
  if (cursor) args.push("-f", `cursor=${cursor}`);
  const raw = execFileSync("gh", args, { encoding: "utf8", maxBuffer: 50 * 1024 * 1024 });
  const data = JSON.parse(raw);
  if (data.errors) {
    console.error(JSON.stringify(data.errors, null, 2).slice(0, 2000));
    process.exit(1);
