import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const token = [REDACTED]("gh", ["auth", "token"], { encoding: "utf8" }).trim();
const headers = { Authorization: `Bearer ${token}`, Accept: "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28", "User-Agent": "tessera-router-eval" };

async function gh(url) {
  for (let attempt = 0; attempt < 4; attempt++) {
    const res = await fetch(url, { headers });
    if (res.status === 403 || res.status === 502 || res.status === 503) {
      await new Promise(r => setTimeout(r, 1000 * (attempt + 1)));
      continue;
    }
    if (res.status === 422) return { error: 422, body: await res.text() };
    if (!res.ok) throw new Error(`${res.status} ${url} ${(await res.text()).slice(0, 300)}`);
    return { json: await res.json() };
  }
  throw new Error("retries exhausted " + url);
}

const pulls = [];
for (let page = 1; page <= 5; page++) {
  const batch = (await gh(`https://api.github.com/repos/vitalitychems-dot/TESSERA/pulls?state=closed&per_page=100&page=${page}&sort=created&direction=asc`)).json;
  pulls.push(...batch.map(p => ({
    number: p.number,
    title: p.title || "",
    body: p.body || "",
    merged: !!p.merged_at,
    created_at: p.created_at,
    changed_files: p.changed_files,
  })));
  if (batch.length < 100) break;
}
console.error("pulls", pulls.length, "zero-changed", pulls.filter(p => !p.changed_files).length);

async function filesFor(p) {
  if (!p.changed_files) return [];
  const files = [];
  for (let page = 1; page <= 20; page++) {
    const res = await gh(`https://api.github.com/repos/vitalitychems-dot/TESSERA/pulls/${p.number}/files?per_page=100&page=${page}`);
    if (res.error) return { error: res.error };
    files.push(...res.json.map(f => f.filename));
    if (res.json.length < 100) break;
  }
  return files;
}

const out = new Array(pulls.length);
let i = 0;
let errors = 0;
async function worker() {
  while (i < pulls.length) {
    const idx = i++;
    const p = pulls[idx];
    const files = await filesFor(p);
    if (files && files.error) {
      errors++;
      out[idx] = { ...p, files: [], file_error: files.error };
    } else {
      out[idx] = { ...p, files };
    }
    if ((idx + 1) % 40 === 0) console.error("done", idx + 1, "errors", errors);
  }
}
await Promise.all(Array.from({ length: 6 }, () => worker()));
writeFileSync("/tmp/tessera-prs.json", JSON.stringify(out));
const ok = out.filter(p => p.files && p.files.length);
console.log(JSON.stringify({
  wrote: out.length,
  withFiles: ok.length,
  errors,
  fileErrorNumbers: out.filter(p => p.file_error).map(p => p.number),
  zero: out.filter(p => !p.changed_files).map(p => p.number),
}));
