import { readFileSync, writeFileSync } from "node:fs";
import { listModules } from "/workspace/artifacts/v2/src/brain/router.mjs";

const MAX_GOLD = 12;
const QUERY_CAP = 4000;
function redact(s) {
  return String(s)
    .replace(/-----BEGIN [A-Z ]+PRIVATE KEY-----[\s\S]*?-----END [A-Z ]+PRIVATE KEY-----/g, "[REDACTED]")
    .replace(/\b(?:ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{20,}\b/g, "[REDACTED]")
    .replace(/\bgithub_pat_[A-Za-z0-9_]{20,}\b/g, "[REDACTED]")
    .replace(/\bsk-[A-Za-z0-9]{20,}\b/g, "[REDACTED]")
    .replace(/\bAKIA[0-9A-Z]{16}\b/g, "[REDACTED]")
    .replace(/\bxox[baprs]-[A-Za-z0-9-]{10,}\b/g, "[REDACTED]");
}
function prepareQuery(title, body) {
  let b = String(body || "");
  b = b.replace(/<!--\s*CURSOR_AGENT_PR_BODY_BEGIN\s*-->/g, "");
  const end = b.search(/<!--\s*CURSOR_AGENT_PR_BODY_END\s*-->/);
  if (end >= 0) b = b.slice(0, end);
  const q = `${redact(String(title || "").trim())}\n\n${redact(b).trim()}`.trim();
  return q.length > QUERY_CAP ? q.slice(0, QUERY_CAP) : q;
}

const modules = new Set(listModules("/workspace"));
const pulls = JSON.parse(readFileSync("/tmp/tessera-prs.json", "utf8"));
const items = [];
let droppedNoGold = 0, droppedBig = 0, redacted = 0;
for (const p of pulls) {
  if (!p.files || !p.files.length) continue;
  const gold = [...new Set(p.files.filter((f) => modules.has(f)))].sort();
  if (gold.length < 1) { droppedNoGold++; continue; }
  if (gold.length > MAX_GOLD) { droppedBig++; continue; }
  const query = prepareQuery(p.title, p.body);
  if (!query) continue;
  if (query.includes("[REDACTED]")) redacted++;
  items.push({ id: `pr-${p.number}`, number: p.number, query, gold });
}
items.sort((a, b) => a.number - b.number);
for (let i = 0; i < items.length; i++) items[i].split = i % 2 === 0 ? "dev" : "test";
const evalSet = {
  schema: "tessera-router-eval/v1",
  source: "closed pull requests in vitalitychems-dot/TESSERA (titles and bodies; gold = files the PR changed)",
  catalog: "package/module list (data/rea/registry.json absent)",
  filter: "gold = changed paths that still exist in the workspace module catalog, size 1..12 inclusive",
  split: "sorted by PR number ascending; even index dev, odd index test",
  query: "title + body, cursor agent footer removed, secret-shaped strings redacted, capped at 4000 chars",
  frozen: "before router parameter tuning",
  items,
};
writeFileSync("/tmp/router-eval.json", JSON.stringify(evalSet));
const dev = items.filter(i => i.split === "dev").length;
const test = items.filter(i => i.split === "test").length;
const bytes = Buffer.byteLength(JSON.stringify(evalSet));
console.log(JSON.stringify({ modules: modules.size, items: items.length, dev, test, droppedNoGold, droppedBig, redacted, bytes, goldMean: items.reduce((s,i)=>s+i.gold.length,0)/items.length }, null, 2));
EOF

