import { readFileSync } from "node:fs";
import { buildRouter, tokenize } from "/workspace/artifacts/v2/src/brain/router.mjs";
const evalSet = JSON.parse(readFileSync("/workspace/artifacts/v2/src/brain/router-eval.json", "utf8"));
const dev = evalSet.items.filter((i) => i.split === "dev");
const router = buildRouter("/workspace");

function hits(rankFn) {
  let top1 = 0, top3 = 0;
  for (const item of dev) {
    const ranked = rankFn(item.query);
    const gold = new Set(item.gold);
    if (gold.has(ranked[0]?.path)) top1++;
    if (ranked.slice(0, 3).some((r) => gold.has(r.path))) top3++;
  }
  return { top1, top3 };
}

function mix(alpha) {
  return hits((query) => {
    const bm = router.rank(query, 0);
    const kw = router.baseline(query, 0);
    let bmMax = 0, kwMax = 0;
    for (const r of bm) if (r.score > bmMax) bmMax = r.score;
    for (const r of kw) if (r.score > kwMax) kwMax = r.score;
    bmMax = bmMax || 1; kwMax = kwMax || 1;
    const kwMap = new Map(kw.map((r) => [r.path, r.score / kwMax]));
    const rows = bm.map((r) => ({ path: r.path, score: r.score / bmMax + alpha * (kwMap.get(r.path) || 0) }));
    rows.sort((a, b) => b.score - a.score || a.path.length - b.path.length || (a.path < b.path ? -1 : 1));
    return rows;
  });
}

